import numpy as np

SLOTS = ((18, 21), (26, 29), (34, 37), (42, 45))
ZONES = ((21, 24), (27, 30), (33, 36), (39, 42))
ZONE_CENTERS = (22.5, 28.5, 34.5, 40.5)
FALLBACK_TARGETS = (9, 14, 11, 15)


def engine(grid, action, data):
    g = np.array(grid, copy=True)
    if g.shape != (64, 64):
        return g

    if action == 6:
        x = y = None
        if isinstance(data, dict):
            try:
                x = int(data['x'])
                y = int(data['y'])
            except Exception:
                x = y = None

        if x is not None and y is not None:
            # Click on a bottom tray slot: toggle its selection frame.
            sidx = -1
            if 56 <= y <= 61:
                for i in range(4):
                    L, R = SLOTS[i]
                    if L - 1 <= x <= R + 1:
                        sidx = i
                        break

            if sidx != -1:
                sel = -1
                for i in range(4):
                    L, R = SLOTS[i]
                    if np.all(g[56, L - 1:R + 2] == 0):
                        ok = True
                        for r in range(57, 61):
                            if g[r, L - 1] != 0 or g[r, R + 1] != 0:
                                ok = False
                                break
                        if ok and np.all(g[61, L - 1:R + 2] == 0):
                            sel = i
                            break

                if sel == sidx:
                    L, R = SLOTS[sidx]
                    g[56, L - 1:R + 2] = 4
                    for r in range(57, 61):
                        g[r, L - 1] = 4
                        g[r, R + 1] = 4
                    g[61, L - 1:R + 2] = 4
                else:
                    if sel != -1:
                        L, R = SLOTS[sel]
                        g[56, L - 1:R + 2] = 4
                        for r in range(57, 61):
                            g[r, L - 1] = 4
                            g[r, R + 1] = 4
                        g[61, L - 1:R + 2] = 4

                    L, R = SLOTS[sidx]
                    g[56, L - 1:R + 2] = 0
                    for r in range(57, 61):
                        g[r, L - 1] = 0
                        g[r, R + 1] = 0
                    g[61, L - 1:R + 2] = 0

                return g

            # Click on the central work area while a slot is selected:
            # swap the selected bottom 4x4 tile with the clicked central 4x4 zone.
            zidx = -1
            if 28 <= y <= 31 and 19 <= x <= 44:
                best = 0
                bestdist = abs(x - ZONE_CENTERS[0])
                for i in range(1, 4):
                    d = abs(x - ZONE_CENTERS[i])
                    if d < bestdist:
                        bestdist = d
                        best = i
                zidx = best

            if zidx != -1:
                sel = -1
                for i in range(4):
                    L, R = SLOTS[i]
                    if np.all(g[56, L - 1:R + 2] == 0):
                        ok = True
                        for r in range(57, 61):
                            if g[r, L - 1] != 0 or g[r, R + 1] != 0:
                                ok = False
                                break
                        if ok and np.all(g[61, L - 1:R + 2] == 0):
                            sel = i
                            break

                if sel != -1:
                    L, R = SLOTS[sel]
                    ZL, ZR = ZONES[zidx]

                    old_slot = g[57:61, L:R + 1].copy()
                    old_zone = g[28:32, ZL:ZR + 1].copy()

                    # Clear top and side selection cells; leave the bottom row as observed.
                    g[56, L - 1:R + 2] = 4
                    for r in range(57, 61):
                        g[r, L - 1] = 4
                        g[r, R + 1] = 4

                    g[57:61, L:R + 1] = old_zone
                    g[28:32, ZL:ZR + 1] = old_slot

                    # Advance the right-to-left progress marker on row 53.
                    for c in range(63, -1, -1):
                        if g[53, c] != 3:
                            g[53, c] = 3
                            break

                return g

        return g

    if action == 5:
        sel = -1
        for i in range(4):
            L, R = SLOTS[i]
            if np.all(g[56, L - 1:R + 2] == 0):
                ok = True
                for r in range(57, 61):
                    if g[r, L - 1] != 0 or g[r, R + 1] != 0:
                        ok = False
                        break
                if ok and np.all(g[61, L - 1:R + 2] == 0):
                    sel = i
                    break

        if sel != -1:
            L, R = SLOTS[sel]
            g[56, L - 1:R + 2] = 4
            for r in range(57, 61):
                g[r, L - 1] = 4
                g[r, R + 1] = 4
            g[61, L - 1:R + 2] = 4

            for c in range(63, -1, -1):
                if g[53, c] != 3:
                    g[53, c] = 3
                    break

        return g

    return g


def is_level_complete(grid):
    g = np.array(grid, copy=False)
    if g.shape != (64, 64):
        return False

    targets = []
    item_colors = (9, 11, 14, 15)

    # Read the target order from the top reference panel, left to right.
    for r in range(8):
        row = g[r]
        for c in range(64):
            v = int(row[c])
            if v in item_colors and v not in targets:
                targets.append(v)
                if len(targets) == 4:
                    break
        if len(targets) == 4:
            break

    if len(targets) != 4:
        targets = list(FALLBACK_TARGETS)

    # The four central 4x4 zones must contain the corresponding target colors.
    for i in range(4):
        L, R = ZONES[i]
        if not np.all(g[28:32, L:R + 1] == targets[i]):
            return False

    return True
